import{_ as a,o,c as i,an as t}from"./chunks/framework.B8kq75N3.js";const r="/MAGEMin_C.jl/dev/assets/MAGEMin_framework.CtAoRKP0.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"MAGEMin Toolset","text":"Phase equilibrium modelling","tagline":"A set of tools to compute phase equilibria for Earth-like compositions","actions":[{"theme":"brand","text":"Getting Started","link":"/MAGEMinApp/MAGEMinApp"},{"theme":"alt","text":"MAGEMin_C.jl API 📚","link":"/api"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/ComputationalThermodynamics/MAGEMin_C.jl"}],"image":{"src":"/logo_MAGEMin_julia.png","alt":"MAGEMin"}},"features":[{"icon":"🚀","title":"MAGEMinApp","details":"Effortlessly compute phase diagrams and Pressure-Temperature paths","link":"/MAGEMinApp/MAGEMinApp"},{"icon":"🛠️","title":"MAGEMin_C","details":"Set of functions to freely compute phase equilibrium in Julia","link":"/MAGEMin_C/MAGEMin_C"},{"icon":"💻","title":"MAGEMin","details":"C program backend of MAGEMin","link":"/MAGEMin/MAGEMin"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),l={name:"index.md"};function n(s,e,d,m,c,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="What-is-MAGEMin?" tabindex="-1">What is MAGEMin? <a class="header-anchor" href="#What-is-MAGEMin?" aria-label="Permalink to &quot;What is MAGEMin? {#What-is-MAGEMin?}&quot;">​</a></h2><p><code>MAGEMin</code> is a Gibbs energy minimization solver, which computes the thermodynamically most stable assemblage for a given thermodynamic database and a set of bulk-rock composition, pressure and temperature conditions. It returns the fraction of the stable minerals, their compositions and all thermodynamically-derived parameters such as density, thermal expansivity, heat capacity etc.</p><p><code>MAGEMin</code> backend is written as a parallel C library and uses a combination of linear programming, the extended Partitioning Gibbs free Energy approach and gradient-based local minimization to compute the most stable mineral assemblage. In this, it differs from existing approaches which makes it particularly suitable to utilize modern multicore processors.</p><p>While <code>MAGEMin</code> is the engine for the prediction of the stable phases, it is best used with the <code>Julia</code> interface <a href="https://github.com/ComputationalThermodynamics/MAGEMin_C.jl" target="_blank" rel="noreferrer">MAGEMin_C</a> and/or the web-browser julia <a href="https://github.com/ComputationalThermodynamics/MAGEMinApp.jl" target="_blank" rel="noreferrer">MAGEMinApp</a>.</p><img src="'+r+'" alt="MAGEMin framework" style="max-width:100%;height:auto;display:block;margin:0 auto;"><h2 id="Available-thermodynamic-databases" tabindex="-1">Available thermodynamic databases <a class="header-anchor" href="#Available-thermodynamic-databases" aria-label="Permalink to &quot;Available thermodynamic databases {#Available-thermodynamic-databases}&quot;">​</a></h2><p><code>MAGEMin</code> ships 13 thermodynamic databases - <code>mp</code>, <code>um</code>, <code>mb</code>, <code>mtl</code>, <code>ig</code>, <code>igad</code>, <code>sb11</code>, <code>sb21</code>, <code>sb24</code>, <code>ume</code>, <code>mpe</code>, <code>mbe</code>, and <code>all</code> (a master database unifying every unique solution-phase model across mp/mb/mbe/ig/igd/igad/um/ume/mpe) - plus the DEW aqueous fluid model, available in <code>all</code> and several of the single-system databases.</p><p><strong>→ See the full <a href="./database">Databases information</a> page</strong> for the acronym reference table, per-database chemical systems, phase/end-member listings, and the DEW aqueous fluid model section.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Please keep in mind that the datasets are only calibrated for a limited range of <code>P</code>,<code>T</code> and <code>bulk rock</code> conditions. If you go too far outside those ranges, <code>MAGEMin</code> (or most other thermodynamic software packages for that matter) may not converge or give bogus results. Developing new, more widely applicable, thermodynamic datasets is a huge research topic, which will require funding to develop the models themselves, as well as to perform targeted experiments to calibrate those models.</p></div><h2 id="Citation" tabindex="-1">Citation <a class="header-anchor" href="#Citation" aria-label="Permalink to &quot;Citation {#Citation}&quot;">​</a></h2><p>An open-access paper describing the methodology is published in G-cubed:</p><ul><li>Riel N., Kaus B.J.P., Green E.C.R., Berlie N., (2022) MAGEMin, an Efficient Gibbs Energy Minimizer: Application to Igneous Systems. <em>Geochemistry, Geophysics, Geosystems</em> 23, e2022GC010427 <a href="https://doi.org/10.1029/2022GC010427" target="_blank" rel="noreferrer">https://doi.org/10.1029/2022GC010427</a></li></ul><h2 id="Fundings" tabindex="-1">Fundings <a class="header-anchor" href="#Fundings" aria-label="Permalink to &quot;Fundings {#Fundings}&quot;">​</a></h2><p>Development of this software package was funded by the European Research Council under grant ERC CoG #771143 - <a href="https://magma.uni-mainz.de" target="_blank" rel="noreferrer">MAGMA</a>, and is currently supported by German Research Foundation (DFG) - Project number #521637679</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ul><li><p>Green, E.C.R., Holland, T.J.B., Powell, R., Weller, O.M., &amp; Riel, N. (2025). Journal of Petrology, 66. <a href="https://doi.org/10.1093/petrology/egae079" target="_blank" rel="noreferrer">doi: 10.1093/petrology/egae079</a></p></li><li><p>Weller, O.M., Holland, T.J.B., Soderman, C.R., Green, E.C.R., Powell, R., Beard, C.D., &amp; Riel, N. (2024). New Thermodynamic Models for Anhydrous Alkaline-Silicate Magmatic Systems. Journal of Petrology, 65. <a href="https://doi.org/10.1093/petrology/egae098" target="_blank" rel="noreferrer">doi: 10.1093/petrology/egae098</a></p></li><li><p>Holland, T.J.B., Green, E.C.R., &amp; Powell, R. (2022). A thermodynamic model for feldspars in KAlSi₃O₈-NaAlSi₃O₈-CaAl₂Si₂O₈ for mineral equilibrium calculations. Journal of Metamorphic Geology, 40, 587-600. <a href="https://doi.org/10.1111/jmg.12639" target="_blank" rel="noreferrer">doi: 10.1111/jmg.12639</a></p></li><li><p>Tomlinson, E.L., &amp; Holland, T.J.B. (2021). A Thermodynamic Model for the Subsolidus Evolution and Melting of Peridotite. Journal of Petrology, 62. <a href="https://doi.org/10.1093/petrology/egab012" target="_blank" rel="noreferrer">doi: 10.1093/petrology/egab012</a></p></li><li><p>Holland, T.J.B., Green, E.C.R., &amp; Powell, R. (2018). Melting of Peridotites through to Granites: A Simple Thermodynamic Model in the System KNCFMASHTOCr. Journal of Petrology, 59, 881-900. <a href="https://doi.org/10.1093/petrology/egy048" target="_blank" rel="noreferrer">doi: 10.1093/petrology/egy048</a></p></li><li><p>Green, E.C.R., White, R.W., Diener, J.F.A., Powell, R., Holland, T.J.B., &amp; Palin, R.M. (2016). Activity-composition relations for the calculation of partial melting equilibria in metabasic rocks. Journal of Metamorphic Geology, 34, 845-869. <a href="https://doi.org/10.1111/jmg12211" target="_blank" rel="noreferrer">doi: 10.1111/jmg12211</a></p></li><li><p>White, R.W., Powell, R., Holland, T.J.B., Johnson, T.E., &amp; Green, E.C.R. (2014). New mineral activity-composition relations for thermodynamic calculations in metapelitic systems. Journal of Metamorphic Geology, 32, 261-286. <a href="https://doi.org/10.1111/jmg.12071" target="_blank" rel="noreferrer">doi: 10.1111/jmg.12071</a></p></li><li><p>Holland, T.J.B., &amp; Powell, R.W. (2011). An improved and extended internally consistent thermodynamic dataset for phases of petrological interest, involving a new equation of state for solids. Journal of Metamorphic Geology, 29, 333-383. <a href="https://doi.org/10.1111/j.1525-1314.2010.00923.x" target="_blank" rel="noreferrer">doi: 10.1111/j.1525-1314.2010.00923.x</a></p></li><li><p>Stixrude, L., &amp; Lithgow-Bertelloni, C. (2011). Thermodynamics of mantle minerals - II. Phase equilibria. Geophysical Journal International, 184, 1456-1475. <a href="https://doi.org/10.1111/j.1365-246X.2010.04890.x" target="_blank" rel="noreferrer">doi: 10.1111/j.1365-246X.2010.04890.x</a></p></li><li><p>Stixrude, L., &amp; Lithgow-Bertelloni, C. (2021). Thermal expansivity, heat capacity and isothermal compressibility of the mantle. Geophysical Journal International, 228, 1296-1314. <a href="https://doi.org/10.1093/gji/ggab394" target="_blank" rel="noreferrer">doi: 10.1093/gji/ggab394</a></p></li><li><p>Stixrude, L., &amp; Lithgow-Bertelloni, C. (2024). Thermodynamics of mantle minerals – III: the role of iron. Geophysical Journal International, 237(3), 1699-1733. <a href="https://doi.org/10.1093/gji/ggae126" target="_blank" rel="noreferrer">doi: 10.1093/gji/ggae126</a></p></li><li><p>Evans, K.A., &amp; Frost, B.R. (2021). Deserpentinization in Subduction Zones as a Source of Oxidation in Arcs: a Reality Check. Journal of Petrology, 62(3), egab016. <a href="https://doi.org/10.1093/petrology/egab016" target="_blank" rel="noreferrer">doi: 10.1093/petrology/egab016</a></p></li><li><p>Diener, J.F.A., Powell, R., White, R.W., &amp; Holland, T.J.B. (2007). A new thermodynamic model for clino- and orthoamphiboles in the system Na₂O-CaO-FeO-MgO-Al₂O₃-SiO₂-H₂O-O. Journal of Metamorphic Geology, 25, 631-656.</p></li><li><p>Rebay, G., Powell, R., &amp; Diener, J.F.A. (2022). New activities for the system FeO-MgO-Al₂O₃-SiO₂ with applications to metamorphic rocks. Journal of Metamorphic Geology.</p></li><li><p>Franzolin, E., Schmidt, M.W., &amp; Poli, S. (2011). Ternary Ca–Fe–Mg carbonates: subsolidus phase relations at 3.5 GPa and a thermodynamic solid solution model including order/disorder. Contributions to Mineralogy and Petrology, 161(2), 213-227.</p></li></ul>',16)])])}const u=a(l,[["render",n]]);export{g as __pageData,u as default};
